import {matchingRound,lessonSentences,shuffle,sentenceCorrect,topicStats,activityOf} from './activity-core.mjs';

export function createActiveLearning(ctx){
  const {bank,esc,icon,heading,empty,sourceLink,studyURL,course,getState,history,save,toast}=ctx;
  const $=selector=>document.querySelector(selector);
  let game=null;
  const modes=[['choice','Chọn đáp án','Nhận biết cấu trúc và nghĩa của câu.','target'],['cloze','Tự điền từ','Nhớ và viết đáp án, không có lựa chọn gợi ý.','note'],['correction','Sửa câu sai','Tìm lỗi và sửa theo yêu cầu của từng câu.','refresh'],['translation','Viết câu & nhớ nghĩa','Tự diễn đạt để kiểm tra điều vừa học.','book']];
  const link=(id,view='lesson')=>`#learn?id=${encodeURIComponent(id)}&view=${view}`;
  const stats=()=>topicStats(bank,history());
  const counts=s=>Object.fromEntries(modes.map(([mode])=>[mode,s.questions.filter(q=>activityOf(q)===mode).length]));
  const read=s=>Boolean(getState().lessonRead?.[s.id]);
  function topicActions(s){return `<a class="text-button active-topic-link" href="${link(s.id)}">${icon('book')}Học & chọn cách luyện ${icon('arrow')}</a>`}
  function intro(){return `<section class="active-intro"><div><span class="eyebrow">ĐỌC → TỰ NHỚ → THỰC HÀNH → ÔN LẠI</span><h2>Nhiều cách học từ cùng một tài liệu</h2><p>Đọc quy tắc cùng ví dụ, tự điền từ, sửa lỗi, ghép nghĩa và sắp xếp câu.</p></div><div><a href="#learn" class="btn btn-primary">${icon('spark')}Học chủ động</a><a href="#learn?view=progress" class="text-button">Xem phần cần ôn ${icon('arrow')}</a></div></section>`}
  function topicCard(s){const c=counts(s),sentences=lessonSentences(s);return `<article class="active-topic-card"><div class="active-topic-top"><span>${esc(s.topic)}</span><span class="lesson-read-badge ${read(s)?'is-read':''}">${read(s)?'✓ Đã đọc hiểu':'Bài học từ tài liệu'}</span></div><h2>${esc(s.title)}</h2><p>${esc(course(s.courseId)?.title||'Tài liệu khóa học')}</p><div class="active-topic-counts">${modes.filter(([m])=>c[m]).map(([m,label])=>`<span>${c[m]} ${esc(label.toLowerCase())}</span>`).join('')}${s.cards.length>=2?'<span>Ghép nghĩa</span>':''}${sentences.length?`<span>${sentences.length} câu xếp từ</span>`:''}</div><a class="btn btn-primary" href="${link(s.id)}">${icon('book')}${read(s)?'Học tiếp chủ đề':'Mở bài học'} ${icon('arrow')}</a></article>`}
  function overview(){const all=bank.sets,withSentences=all.filter(s=>lessonSentences(s).length),withPairs=all.filter(s=>s.cards.length>=2);return `${heading('Học chủ động từ tài liệu','Hiểu một quy tắc, thử nhiều cách nhớ, rồi quay lại chỗ mình hay sai.',`<a class="btn btn-secondary" href="#practice">${icon('back')}Bài luyện</a>`)}<section class="active-journey"><div><span class="eyebrow">MỘT BUỔI HỌC NHỎ</span><h2>Đọc hiểu trước. Tự làm để nhớ.</h2><p>Chọn một chủ đề bên dưới. Mỗi bài có quy tắc, ví dụ và các kiểu luyện phù hợp với nội dung đã đọc.</p></div><a class="btn btn-primary" href="#quiz?id=smart">${icon('target')}Ôn 10 câu cho tôi</a></section><div class="active-capabilities"><div>${icon('note')}<strong>Điền từ & sửa lỗi</strong><p>Tự viết câu trả lời, có giải thích sau khi nộp.</p></div><div>${icon('book')}<strong>Ghép từ với nghĩa</strong><p>${withPairs.length} bộ từ vựng có trò ghép cặp.</p></div><div>${icon('route')}<strong>Sắp xếp câu</strong><p>${withSentences.length} chủ đề có ví dụ để xếp từ.</p></div><div>${icon('chart')}<strong>Theo dõi chỗ cần ôn</strong><p>Tính từ câu đã làm, không suy đoán điểm thi.</p></div></div><div class="active-section-heading"><h2>Chọn một bài để bắt đầu</h2><a class="text-button" href="#learn?view=progress">Điểm mạnh & phần cần ôn ${icon('arrow')}</a></div><label class="active-course-filter">Khóa học<select id="active-course-filter"><option value="">Tất cả khóa đã có nội dung</option>${[...new Set(all.map(s=>s.courseId))].map(id=>`<option value="${id}">${esc(course(id)?.title||id)}</option>`).join('')}</select></label><div class="active-topics-grid" id="active-topics-grid">${all.map(topicCard).join('')}</div><p class="fine-print active-storage-note">Nội dung tóm tắt và ví dụ do ứng dụng biên soạn theo những trang nguồn đã đọc. Các tài liệu khác vẫn học bằng trình xem và phiếu tự đối chiếu.</p>`}
  function insights(){const rows=stats(),attempted=rows.reduce((n,r)=>n+r.attempted,0),correct=rows.reduce((n,r)=>n+r.correct,0),readCount=bank.sets.filter(read).length,games=getState().games||[];return `${heading('Biết mình cần luyện gì tiếp theo','Mỗi câu chỉ tính kết quả gần nhất. Dữ liệu cũ chưa có điểm theo câu được giữ số câu đã thử; tỷ lệ đúng chỉ tính những câu có kết quả đã ghi nhận.',`<a class="btn btn-secondary" href="#learn">${icon('back')}Học chủ động</a>`)}<div class="learning-stat-strip"><span><strong>${attempted}</strong> câu đã thử trả lời</span><span><strong>${rows.some(r=>r.accuracy!==null)?Math.round(100*correct/Math.max(1,rows.filter(r=>r.accuracy!==null).reduce((n,r)=>n+r.correct+r.wrong,0)))+'%':'—'}</strong> đúng trong lần trả lời gần nhất</span><span><strong>${readCount}</strong> bài đã đánh dấu đọc hiểu</span><span><strong>${games.length}</strong> lượt chơi gần đây</span></div><section class="active-journey compact"><div><h2>${getState().wrong.length?'Quay lại đúng phần đang vướng':'Thêm một lượt luyện ngắn'}</h2><p>Buổi 10 câu ưu tiên câu bạn đã sai, sau đó đến chủ đề ít được luyện.</p></div><a class="btn btn-primary" href="#quiz?id=smart">${icon('target')}Bắt đầu 10 câu</a></section><div class="topic-progress-list">${rows.slice().sort((a,b)=>(a.attempted?0:1)-(b.attempted?0:1)||(a.accuracy??101)-(b.accuracy??101)).map(r=>{const s=bank.sets.find(s=>s.id===r.setId);return `<article><div class="topic-progress-copy"><small>${r.attempted?r.wrong?'CÒN CÂU CẦN XEM LẠI':'ĐÃ CÓ BƯỚC TIẾN':'CHƯA LUYỆN CHỦ ĐỀ NÀY'}</small><h2>${esc(s.title)}</h2><p>${r.attempted}/${r.total} câu đã trả lời · ${r.correct} đúng · ${r.unseen} câu chưa thử${r.attempted&&r.accuracy===null?' · dữ liệu cũ chưa có điểm theo câu':''}</p><div class="progress-track"><span style="width:${100*r.attempted/Math.max(1,r.total)}%"></span></div></div><strong class="topic-accuracy">${r.accuracy===null?'—':r.accuracy+'%'}<small>đúng gần nhất</small></strong><a class="btn btn-soft" href="${link(s.id)}">${r.wrong?'Ôn chủ đề này':'Mở bài học'} ${icon('arrow')}</a></article>`}).join('')}</div><p class="fine-print active-storage-note">Đây là kết quả trên các câu đã luyện trong ứng dụng; không phải đánh giá toàn bộ khóa hay dự đoán điểm TOEIC. ${games.length?'Ghép nghĩa và xếp câu lưu thành lượt chơi riêng, không cộng vào tỷ lệ câu hỏi.':''}</p>`}
  function modeCards(s){const c=counts(s),sentences=lessonSentences(s);return `<div class="activity-mode-list">${modes.filter(([m])=>c[m]).map(([m,label,description,ic])=>`<a href="#quiz?id=${s.id}&mode=${m}"><span class="activity-mode-icon">${icon(ic)}</span><div><strong>${esc(label)}</strong><p>${esc(description)}</p><small>${c[m]} câu</small></div>${icon('chevron')}</a>`).join('')}${s.cards.length>=2?`<a href="${link(s.id,'match')}"><span class="activity-mode-icon">${icon('book')}</span><div><strong>Ghép từ với nghĩa</strong><p>Chọn một từ rồi chọn nghĩa tương ứng.</p><small>${s.cards.length} thẻ trong bộ</small></div>${icon('chevron')}</a>`:''}${sentences.length?`<a href="${link(s.id,'order')}"><span class="activity-mode-icon">${icon('route')}</span><div><strong>Sắp xếp câu</strong><p>Ghép các từ thành câu theo ví dụ của bài.</p><small>${sentences.length} câu</small></div>${icon('chevron')}</a>`:''}</div>`}
  function lesson(s){const sections=s.lesson?.sections||[],readAlready=read(s);return `${topicHeader(s,'Hiểu bài rồi chọn một cách luyện bên dưới.',true)}<div class="active-lesson-layout"><section class="active-reading"><div class="lesson-overview"><span class="eyebrow">Ý CHÍNH CẦN NHỚ</span><ul>${s.summary.map(point=>`<li>${esc(point)}</li>`).join('')}</ul><p>Phần đọc và ví dụ dưới đây được ứng dụng biên soạn từ tài liệu nguồn.</p></div>${sections.length?sections.map((section,i)=>`<article class="lesson-section"><span class="lesson-section-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(section.heading)}</h2><ul>${section.points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul>${section.examples?.length?`<div class="lesson-examples">${section.examples.map(example=>`<div><strong>${esc(example.en)}</strong><span>${esc(example.vi)}</span></div>`).join('')}</div>`:''}${sourceLink(section.sourceId,section.page,'Trang nguồn của phần này')}</article>`).join(''):`<article class="lesson-section"><h2>Đối chiếu với bài gốc</h2><p>Mở trang nguồn, đọc quy tắc rồi thử bài luyện ở bên cạnh.</p>${s.sources.map(source=>sourceLink(source.id,source.pages[0])).join('')}</article>`}${s.lesson?.pitfalls?.length?`<article class="lesson-pitfalls"><h2>${icon('spark')}Những chỗ dễ nhầm</h2><ul>${s.lesson.pitfalls.map(point=>`<li>${esc(point)}</li>`).join('')}</ul></article>`:''}<div class="lesson-finish"><button class="btn ${readAlready?'btn-soft':'btn-primary'}" data-active-read="${s.id}" aria-pressed="${readAlready}">${icon('check')}${readAlready?'Đã đánh dấu đọc hiểu':'Mình đã đọc và hiểu bài'}</button><a class="text-button" href="${studyURL(s.courseId,s.folderId,s.sources[0].id)}">Video & tài liệu gốc ${icon('external')}</a></div></section><aside class="active-lesson-practice" id="active-lesson-practice"><h2>Chọn cách luyện</h2><p>Thử tự nhớ trước khi xem đáp án.</p>${modeCards(s)}<a class="text-button" href="#quiz?id=${s.id}">Làm toàn bộ ${s.questions.length} câu ${icon('arrow')}</a></aside></div>`}
  function topicHeader(s,subtitle,lesson=false){return `<nav class="content-breadcrumbs"><a href="#learn">Học chủ động</a><span>›</span><a href="${link(s.id)}">${esc(s.title)}</a></nav>${heading(esc(s.title),esc(subtitle),lesson?`<button class="btn btn-primary" data-active-jump>${icon('target')}Chọn cách luyện</button>`:`<a class="btn btn-secondary" href="${link(s.id)}">${icon('book')}Đọc lại bài</a>`)}`}
  function startMatch(s){const round=matchingRound(s.cards,6);return {key:s.id+':match',type:'match',set:s,...round,selectedLeft:null,selectedRight:null,matched:[],tries:0,feedback:'',saved:false}}
  function startOrder(s){const sentences=lessonSentences(s);return {key:s.id+':order',type:'order',set:s,sentences,position:0,selected:[],pool:shuffle((sentences[0]?.words||[]).map((text,id)=>({text,id}))),tries:0,firstCorrect:0,currentAttempts:0,solved:false,feedback:'',hint:false,revealed:false,saved:false}}
  function gamePage(s,view){if(view==='match'&&s.cards.length<2||view==='order'&&!lessonSentences(s).length)return `${topicHeader(s,'Chọn kiểu luyện có nội dung trong bài này.')}<div class="active-reading">${modeCards(s)}</div>`;if(game?.key!==s.id+':'+view)game=view==='match'?startMatch(s):startOrder(s);return `${topicHeader(s,view==='match'?'Ghép đúng từ với nghĩa. Mỗi lượt chọn tối đa 6 cặp từ.':'Chọn các từ theo thứ tự để viết lại câu. Bấm vào từ đã chọn để bỏ ra.')}<div id="active-game-workspace"></div><p class="fine-print active-storage-note">Lượt chơi được lưu khi hoàn thành. Có thể chơi lại để nhận thứ tự từ mới.</p>`}
  function storeGame(type,total,correct,tries){if(game.saved)return;const state=getState();state.games||=[];state.games.push({setId:game.set.id,type,total,correct,tries,date:new Date().toISOString()});state.games=state.games.slice(-100);save();game.saved=true}
  function gameSummary(title,description){return `<section class="active-game-result">${icon('check')}<h2>${esc(title)}</h2><p>${esc(description)}</p><div><button class="btn btn-primary" data-active-restart>Chơi lại</button><a class="btn btn-secondary" href="${link(game.set.id)}">Chọn cách luyện khác</a><a class="text-button" href="#learn?view=progress">Xem tiến bộ ${icon('arrow')}</a></div></section>`}
  function drawMatch(){const g=game;if(g.matched.length===g.pairs.length){storeGame('match',g.pairs.length,g.pairs.length,g.tries);$('#active-game-workspace').innerHTML=gameSummary('Đã ghép đủ '+g.pairs.length+' cặp',`${g.tries} lần thử để ghép ${g.pairs.length} cặp. Mở lại thẻ từ nếu còn từ chưa chắc.`)+`<div class="matched-review">${g.pairs.map(card=>`<article><strong>${esc(card.front)}</strong><span>${esc(card.back)}</span>${sourceLink(card.sourceId,card.page)}</article>`).join('')}</div>`;return}
    const column=(items,side)=>items.map(item=>{const done=g.matched.includes(item.id),selected=(side==='left'?g.selectedLeft:g.selectedRight)===item.id;return `<button class="match-tile ${done?'matched':''} ${selected?'selected':''}" data-active-match="${item.id}" data-side="${side}" aria-pressed="${selected}" ${done?'disabled':''}>${done?icon('check'):''}<span>${esc(item.text)}</span></button>`}).join('');
    $('#active-game-workspace').innerHTML=`<section class="matching-game"><div class="active-game-status"><strong>${g.matched.length}/${g.pairs.length} cặp đã ghép</strong><span>${g.tries} lần thử</span></div><div class="matching-columns"><div><h2>Từ tiếng Anh</h2>${column(g.left,'left')}</div><div><h2>Nghĩa tiếng Việt</h2>${column(g.right,'right')}</div></div><p class="active-feedback" role="status">${esc(g.feedback||'Chọn một từ ở bên trái, rồi chọn nghĩa bên phải.')}</p><a class="text-button" href="#cards?id=${g.set.id}">Ôn bằng thẻ từ ${icon('arrow')}</a></section>`;
  }
  function chooseMatch(id,side){const g=game;if(g.matched.includes(id))return;g[side==='left'?'selectedLeft':'selectedRight']=id;if(g.selectedLeft&&g.selectedRight){g.tries++;if(g.selectedLeft===g.selectedRight){g.matched.push(id);g.feedback='Chính xác! Tiếp tục với cặp tiếp theo.'}else g.feedback='Hai mục này chưa khớp. Chọn lại một cặp khác nhé.';g.selectedLeft=null;g.selectedRight=null}drawMatch()}
  function drawOrder(){const g=game,item=g.sentences[g.position];if(!item){storeGame('order',g.sentences.length,g.firstCorrect,g.tries);$('#active-game-workspace').innerHTML=gameSummary('Đã luyện xong '+g.sentences.length+' câu',`${g.firstCorrect}/${g.sentences.length} câu tự xếp đúng ngay lần kiểm tra đầu tiên, không cần gợi ý hay đáp án.`);return}
    $('#active-game-workspace').innerHTML=`<section class="sentence-game"><div class="active-game-status"><strong>Câu ${g.position+1}/${g.sentences.length}</strong><span>${g.firstCorrect} câu đúng ngay lần đầu</span></div><p class="sentence-meaning">${esc(item.meaning||'Sắp xếp lại câu ví dụ trong bài học.')}</p><div class="sentence-answer" aria-label="Câu đang sắp xếp">${g.selected.length?g.selected.map((id,i)=>`<button data-active-remove="${i}" aria-label="Bỏ từ ${esc(g.pool.find(token=>token.id===id).text)}" ${g.solved?'disabled':''}>${esc(g.pool.find(token=>token.id===id).text)}</button>`).join(''):'<span>Chọn từ ở dưới để tạo câu…</span>'}</div><div class="sentence-word-pool">${g.pool.map(token=>`<button data-active-word="${token.id}" ${g.selected.includes(token.id)||g.solved?'disabled':''}>${esc(token.text)}</button>`).join('')}</div><p class="active-feedback ${g.solved?'positive':''}" role="status">${esc(g.feedback||'Bạn có thể bấm từ trong câu phía trên để bỏ ra và chọn lại.')}</p>${g.hint&&!g.solved?`<p class="sentence-hint">Gợi ý: câu bắt đầu bằng “${esc(item.words[0])}”.</p>`:''}${g.revealed?`<div class="sentence-solution"><strong>${esc(item.answer)}</strong><p>Đọc lại cấu trúc rồi thử tự xếp câu tiếp theo.</p></div>`:''}<div class="sentence-actions">${g.solved?`<button class="btn btn-primary" data-active-order-next>${g.position===g.sentences.length-1?'Xem kết quả':'Câu tiếp'} ${icon('arrow')}</button>`:`<button class="btn btn-primary" data-active-order-check>${icon('check')}Kiểm tra câu</button><button class="btn btn-secondary" data-active-order-clear>Làm lại câu</button><button class="text-button" data-active-order-hint>Gợi ý</button><button class="text-button" data-active-order-reveal>Xem đáp án</button>`}</div>${sourceLink(item.sourceId,item.page,'Nguồn của ví dụ biên soạn')}</section>`;
  }
  function checkOrder(){const g=game,item=g.sentences[g.position];if(g.selected.length!==g.pool.length){g.feedback='Hãy dùng đủ các từ trước khi kiểm tra.';drawOrder();return}g.tries++;g.currentAttempts++;const selected=g.selected.map(id=>g.pool.find(token=>token.id===id).text);if(sentenceCorrect(selected,item)){g.solved=true;if(g.currentAttempts===1&&!g.revealed&&!g.hint)g.firstCorrect++;g.feedback='Đúng rồi! Bạn đã xếp đúng câu ví dụ.'}else g.feedback='Thứ tự chưa khớp câu mẫu của bài. Thử lại hoặc mở đáp án để đối chiếu.';drawOrder()}
  function page(params){const view=params.get('view')||'lesson',s=bank.sets.find(s=>s.id===params.get('id'));if(!params.get('id'))return view==='progress'?insights():overview();if(!s)return empty('Chưa tìm thấy chủ đề','Chọn một bài học từ danh sách.','book','<a class="btn btn-primary" href="#learn">Chọn bài học</a>');return ['match','order'].includes(view)?gamePage(s,view):lesson(s)}
  function afterRender(){$('#main').classList.toggle('active-study-view',Boolean($('.active-lesson-layout')||$('#active-game-workspace')));if(!$('#active-game-workspace')){game=null;return}if(game.type==='match')drawMatch();else drawOrder()}
  document.addEventListener('change',event=>{if(event.target.id==='active-course-filter')$('#active-topics-grid').innerHTML=bank.sets.filter(s=>!event.target.value||s.courseId===event.target.value).map(topicCard).join('')});
  document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-active-jump')){$('#active-lesson-practice')?.scrollIntoView({block:'start',behavior:'smooth'});return}if(button.hasAttribute('data-active-read')){const state=getState();state.lessonRead||={};const id=button.dataset.activeRead;if(state.lessonRead[id])delete state.lessonRead[id];else state.lessonRead[id]=new Date().toISOString();save();button.classList.toggle('btn-soft',Boolean(state.lessonRead[id]));button.classList.toggle('btn-primary',!state.lessonRead[id]);button.setAttribute('aria-pressed',String(Boolean(state.lessonRead[id])));button.innerHTML=icon('check')+(state.lessonRead[id]?'Đã đánh dấu đọc hiểu':'Mình đã đọc và hiểu bài');return}
    if(!game||!$('#active-game-workspace'))return;
    if(button.hasAttribute('data-active-match'))chooseMatch(button.dataset.activeMatch,button.dataset.side);
    else if(button.hasAttribute('data-active-restart')){game=game.type==='match'?startMatch(game.set):startOrder(game.set);afterRender()}
    else if(button.hasAttribute('data-active-word')&&!game.solved){game.selected.push(Number(button.dataset.activeWord));game.feedback='';drawOrder()}
    else if(button.hasAttribute('data-active-remove')&&!game.solved){game.selected.splice(Number(button.dataset.activeRemove),1);game.feedback='';drawOrder()}
    else if(button.hasAttribute('data-active-order-check'))checkOrder();
    else if(button.hasAttribute('data-active-order-clear')){game.selected=[];game.feedback='';drawOrder()}
    else if(button.hasAttribute('data-active-order-hint')){game.hint=true;drawOrder()}
    else if(button.hasAttribute('data-active-order-reveal')){game.revealed=true;game.solved=true;game.tries++;game.feedback='Đã mở đáp án; câu này không tính là tự xếp đúng ngay lần đầu.';drawOrder()}
    else if(button.hasAttribute('data-active-order-next')){game.position++;game.selected=[];game.currentAttempts=0;game.solved=false;game.hint=false;game.revealed=false;game.feedback='';game.pool=shuffle((game.sentences[game.position]?.words||[]).map((text,id)=>({text,id})));drawOrder()}
  });
  return {page,afterRender,intro,topicActions};
}
